from math import isqrt
from typing import Iterator, Optional, Tuple

def continued_fraction(num: int, den: int) -> Iterator[int]:
    while den:
        a = num // den
        yield a
        num, den = den, num - a * den

def convergents(num: int, den: int) -> Iterator[Tuple[int, int]]:
    h_prev, h_cur, k_prev, k_cur = 0, 1, 1, 0
    for a in continued_fraction(num, den):
        h_prev, h_cur = h_cur, a * h_cur + h_prev
        k_prev, k_cur = k_cur, a * k_cur + k_prev
        yield h_cur, k_cur

def smallness_condition(d: int, k: int, delta: int, nt: int) -> bool:
    """The partial-knowledge smallness condition 2*d*(k*Delta + 1) < ntilde."""
    return 2 * d * (k * delta + 1) < nt

def modified_wiener_attack(n: int, e: int, s: int, delta: int
                           ) -> Optional[Tuple[int, int, int, int]]:
    """Factor n from public (n, e) and an estimate s of p+q with |p+q - s| <= delta.

    Returns (p, q, d, k) if successful, else None. Runs in O(log^2 n) bit operations:
    O(log n) convergents, each tested with a constant number of big-integer ops.
    """
    nt = n + 1 - s
    for k_cand, d_cand in convergents(e, nt):
        if k_cand < 1 or d_cand < 1:
            continue
        if not smallness_condition(d_cand, k_cand, delta, nt):
            continue
        if (e * d_cand - 1) % k_cand != 0:
            continue
        phi_star = (e * d_cand - 1) // k_cand     # candidate Euler totient
        prime_sum = n + 1 - phi_star              # candidate p + q
        disc = prime_sum * prime_sum - 4 * n
        if disc < 0:
            continue
        r = isqrt(disc)
        if r * r != disc:
            continue
        p = (prime_sum + r) // 2
        q = (prime_sum - r) // 2
        if p * q == n:
            return (max(p, q), min(p, q), d_cand, k_cand)
    return None
